// AdminStats is the resolver for the adminStats field.
func (r *queryResolver) AdminStats(ctx context.Context) (*model.AdminStats, error) {
	userIDVal := ctx.Value(userIDKey)
	if userIDVal == nil {
		// Debug: try different context keys
		if v := ctx.Value("userID"); v != nil {
			userIDVal = v
		} else {
			// Try the server.UserIDKey directly
			if v := ctx.Value(server.UserIDKey); v != nil {
				userIDVal = v
			} else {
				return nil, fmt.Errorf("unauthenticated - no user context found")
			}
		}
	}
	userID := userIDVal.(string)

	// Check if user is admin (you might want to implement proper admin check)
	var userRole string
	err := r.DB.Get(&userRole, "SELECT role FROM users WHERE id = $1", userID)
	if err != nil {
		return nil, fmt.Errorf("failed to get user role: %v", err)
	}
	if userRole != "admin" {
		return nil, fmt.Errorf("forbidden")
	}

	// Get admin statistics
	var totalUsers, totalFileObjects, totalUserFiles int
	var deduplicatedStorageBytes, logicalStorageBytes int64

	// Count users
	err = r.DB.Get(&totalUsers, "SELECT COUNT(*) FROM users")
	if err != nil {
		return nil, fmt.Errorf("failed to count users: %v", err)
	}

	// Count file objects (unique files)
	err = r.DB.Get(&totalFileObjects, "SELECT COUNT(*) FROM file_objects")
	if err != nil {
		return nil, fmt.Errorf("failed to count file objects: %v", err)
	}

	// Count user files (file references)
	err = r.DB.Get(&totalUserFiles, "SELECT COUNT(*) FROM user_files")
	if err != nil {
		return nil, fmt.Errorf("failed to count user files: %v", err)
	}

	// Calculate storage statistics
	err = r.DB.Get(&deduplicatedStorageBytes, "SELECT COALESCE(SUM(size_bytes), 0) FROM file_objects")
	if err != nil {
		return nil, fmt.Errorf("failed to calculate deduplicated storage: %v", err)
	}

	// Calculate logical storage (what it would be without deduplication)
	err = r.DB.Get(&logicalStorageBytes, `
		SELECT COALESCE(SUM(fo.size_bytes), 0) 
		FROM user_files uf 
		JOIN file_objects fo ON uf.file_object_id = fo.id
	`)
	if err != nil {
		return nil, fmt.Errorf("failed to calculate logical storage: %v", err)
	}

	dedupSavingsBytes := logicalStorageBytes - deduplicatedStorageBytes

	return &model.AdminStats{
		TotalUsers:               totalUsers,
		TotalFileObjects:         totalFileObjects,
		TotalUserFiles:           totalUserFiles,
		DeduplicatedStorageBytes: int(deduplicatedStorageBytes),
		LogicalStorageBytes:      int(logicalStorageBytes),
		DedupSavingsBytes:        int(dedupSavingsBytes),
	}, nil
}

