// FilesByTag is the resolver for the filesByTag field.
func (r *queryResolver) FilesByTag(ctx context.Context, tagName string, pagination *model.PaginationInput) (*model.FilePage, error) {
	limit := 20
	offset := 0
	if pagination != nil {
		if pagination.Limit != nil {
			limit = *pagination.Limit
		}
		if pagination.Offset != nil {
			offset = *pagination.Offset
		}
	}

	fileIDs, totalCount, err := db.GetFilesByTag(ctx, r.DB, tagName, limit, offset)
	if err != nil {
		return nil, err
	}

	// Convert file IDs to UserFile objects
	userFiles := make([]*model.UserFile, 0, len(fileIDs))
	for _, fileID := range fileIDs {
		userFile, err := r.getUserFileByID(ctx, fileID)
		if err != nil {
			continue // Skip files that can't be loaded
		}
		userFiles = append(userFiles, userFile)
	}

	return &model.FilePage{
		Items:      userFiles,
		TotalCount: totalCount,
	}, nil
}

