// ShareFolder is the resolver for the shareFolder field.
func (r *mutationResolver) ShareFolder(ctx context.Context, folderID string, public *bool, expiresAt *time.Time, maxDownloads *int) (*model.ShareCreatePayload, error) {
	userIDVal := ctx.Value(userIDKey)
	if userIDVal == nil {
		// Debug: try different context keys
		if v := ctx.Value("userID"); v != nil {
			userIDVal = v
		} else {
			// Try the server.UserIDKey directly
			if v := ctx.Value(server.UserIDKey); v != nil {
				userIDVal = v
			} else {
				return nil, fmt.Errorf("unauthenticated - no user context found")
			}
		}
	}
	userID := userIDVal.(string)

	// Verify folder ownership
	folder, err := db.GetFolder(ctx, r.DB.DB, folderID)
	if err != nil {
		return nil, fmt.Errorf("folder not found")
	}
	if folder.OwnerID != userID {
		return nil, fmt.Errorf("only folder owner can share")
	}

	token, err := crypto.GenerateShareToken(18)
	if err != nil {
		return nil, fmt.Errorf("failed to generate token")
	}

	publicVal := true
	if public != nil {
		publicVal = *public
	}

	share := db.Share{
		FileID:       nil,
		FolderID:     &folderID,
		OwnerID:      userID,
		Token:        token,
		Public:       publicVal,
		ExpiresAt:    expiresAt,
		MaxDownloads: maxDownloads,
	}

	created, err := db.CreateShare(ctx, r.DB.DB, share)
	if err != nil {
		return nil, fmt.Errorf("failed to create share")
	}

	baseURL := "http://localhost:8080" // TODO: make configurable
	url := baseURL + "/s/" + created.Token
	return &model.ShareCreatePayload{
		Token:     created.Token,
		URL:       url,
		ExpiresAt: created.ExpiresAt,
	}, nil
}

