// getUserFileByID is a helper function to get a UserFile by ID
func (r *Resolver) getUserFileByID(ctx context.Context, userFileID string) (*model.UserFile, error) {
	type userFileRow struct {
		UserFileID   string `db:"user_file_id"`
		UserID       string `db:"user_id"`
		UserEmail    string `db:"user_email"`
		FileObjectID string `db:"file_object_id"`
		Filename     string `db:"filename"`
		Visibility   string `db:"visibility"`
		UploadedAt   string `db:"uploaded_at"`
		Hash         string `db:"hash"`
		StoragePath  string `db:"storage_path"`
		SizeBytes    int64  `db:"size_bytes"`
		MimeType     string `db:"mime_type"`
		RefCount     int    `db:"ref_count"`
		CreatedAt    string `db:"created_at"`
	}
	
	var row userFileRow
	query := `
		SELECT 
			uf.id as user_file_id,
			uf.user_id,
			u.email as user_email,
			uf.file_object_id,
			uf.filename,
			COALESCE(uf.visibility, 'private') as visibility,
			uf.uploaded_at,
			fo.hash,
			fo.storage_path,
			fo.size_bytes,
			fo.mime_type,
			fo.ref_count,
			fo.created_at
		FROM user_files uf
		JOIN users u ON uf.user_id = u.id
		JOIN file_objects fo ON uf.file_object_id = fo.id
		WHERE uf.id = $1`
	
	err := r.DB.GetContext(ctx, &row, query, userFileID)
	if err != nil {
		return nil, err
	}
	
	// Parse timestamps
	uploadedAt, _ := time.Parse(time.RFC3339, row.UploadedAt)
	createdAt, _ := time.Parse(time.RFC3339, row.CreatedAt)
	
	return &model.UserFile{
		ID: row.UserFileID,
		User: &model.User{
			ID:    row.UserID,
			Email: row.UserEmail,
			Role:  "user", // Default role
		},
		FileObject: &model.FileObject{
			ID:          row.FileObjectID,
			Hash:        row.Hash,
			StoragePath: row.StoragePath,
			SizeBytes:   int(row.SizeBytes),
			MimeType:    &row.MimeType,
			RefCount:    row.RefCount,
			CreatedAt:   createdAt,
		},
		Filename:   row.Filename,
		Visibility: row.Visibility,
		UploadedAt: uploadedAt,
	}, nil
}



// Mutation returns generated.MutationResolver implementation.
func (r *Resolver) Mutation() generated.MutationResolver { return &mutationResolver{r} }

// Query returns generated.QueryResolver implementation.
func (r *Resolver) Query() generated.QueryResolver { return &queryResolver{r} }

type mutationResolver struct{ *Resolver }
type queryResolver struct{ *Resolver }
